import { ANONYMOUS_RESULT_OWNER, isAnonymousUserId } from '../auth/anonymous-identity';

/**
 * Namespaces of storage keys. Every key is generated by the server; callers never choose one.
 * - `uploads/<userId>/...`: staged inputs and user-scoped uploads owned by that user (`userUploadPrefix`).
 * - `uploads/...`: capability-scoped multipart or anonymous staged uploads that carry no owner segment.
 * - `conversions/<userId>/...`: synchronous API outputs and account multipart uploads owned by that user. The results of an
 *   anonymous caller are under the constant owner `anon:result` (`resultKey`), reachable by anyone holding the key.
 * - `results/<jobId>/...`: queue job outputs, owned by the job's user when the job has one. A graph's exports are
 *   `results/<graphId>/<nodeId>/<index>/<name>` (`nodeOutputKey`), read as outputs of the job the graph id names.
 * - `intermediate/<graphId>/<nodeId>/...`: outputs of the nodes of a job graph, inheriting ownership from their graph
 *   state (`ownerUserId`) when registered (capability access for anonymous graphs, fail-closed when missing or ended).
 * Any other key is `other`: no writer of the server produces one, and keys with traversal or empty path segments fail
 * closed here so no route serves or resolves them.
 */
export type StorageKeyNamespace =
  | { namespace: 'upload' }
  | { namespace: 'user-upload'; userId: string }
  | { namespace: 'user-conversion'; userId: string }
  | { namespace: 'job-result'; jobId: string }
  | { namespace: 'intermediate' }
  | { namespace: 'other' };

const UPLOAD_KEY_PREFIX = 'uploads/';
const INLINE_INPUT_KEY = 'inline';
const INLINE_INPUT_KEY_PREFIX = 'inline:';
const USER_UPLOAD_KEY_PATTERN =
  /^uploads\/((?:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|user[_-][^/]+))\/[\s\S]+$/i;
const USER_CONVERSION_KEY_PATTERN = /^conversions\/([^/]+)\//;
const JOB_RESULT_KEY_PATTERN = /^results\/([^/]+)\//;
const GRAPH_NODE_OUTPUT_KEY_PATTERN = /^intermediate\/[^/]+\/[^/]+\//;

/** Whether a key is in the ownerless multipart upload namespace. */
export function isUploadKey(key: string): boolean {
  return key.startsWith(UPLOAD_KEY_PREFIX);
}

/**
 * Whether a graph node's `storageKey` is the placeholder the server writes for an input that came in the request body
 * (`inline`, or `inline:<filename>`) and not a stored file. A key that only begins with "inline" is a stored key.
 */
export function isInlineInputKey(key: string): boolean {
  return key === INLINE_INPUT_KEY || key.startsWith(INLINE_INPUT_KEY_PREFIX);
}

/**
 * The key of a new multipart upload named `uniqueName`: under `conversions/<owner>/` for an account, and in the
 * ownerless upload namespace for an anonymous caller or none, so that no key carries an anonymous identity.
 */
export function multipartUploadKey(ownerUserId: string | undefined, uniqueName: string): string {
  return ownerUserId && !isAnonymousUserId(ownerUserId) ? `${userConversionPrefix(ownerUserId)}${uniqueName}` : `${UPLOAD_KEY_PREFIX}${uniqueName}`;
}

/**
 * The key of a retained result of `ownerUserId` named `uniqueName`: under the account's own prefix, and under the constant owner of
 * anonymous results for an anonymous caller, whose id is its address bucket and must not appear in a key.
 */
export function resultKey(ownerUserId: string, uniqueName: string): string {
  return `${userConversionPrefix(isAnonymousUserId(ownerUserId) ? ANONYMOUS_RESULT_OWNER : ownerUserId)}${uniqueName}`;
}

/**
 * The key of a file a route stages as the input of a worker for `ownerUserId`: under `uploads/<account>/` for an account and in the
 * ownerless upload namespace for an anonymous caller (as `multipartUploadKey` puts every upload of an anonymous caller).
 */
export function stagedInputKey(ownerUserId: string, uniqueName: string): string {
  return isAnonymousUserId(ownerUserId) ? `${UPLOAD_KEY_PREFIX}${uniqueName}` : `${userUploadPrefix(ownerUserId)}${uniqueName}`;
}

/** The prefix of the keys `userId` owns under `uploads/`, with its closing slash so that no other user's prefix matches. */
export function userUploadPrefix(userId: string): string {
  return `${UPLOAD_KEY_PREFIX}${userId}/`;
}

/** The prefix of the keys `userId` owns under `conversions/`, with its closing slash so that no other user's prefix matches. */
export function userConversionPrefix(userId: string): string {
  return `conversions/${userId}/`;
}

export function classifyStorageKey(key: string): StorageKeyNamespace {
  if (key.split('/').some((segment) => segment === '' || segment === '.' || segment === '..')) {
    return { namespace: 'other' };
  }

  const userUpload = USER_UPLOAD_KEY_PATTERN.exec(key);
  if (userUpload) {
    return { namespace: 'user-upload', userId: userUpload[1] };
  }

  if (isUploadKey(key)) {
    return { namespace: 'upload' };
  }

  const userConversion = USER_CONVERSION_KEY_PATTERN.exec(key);
  if (userConversion) {
    return { namespace: 'user-conversion', userId: userConversion[1] };
  }

  const jobResult = JOB_RESULT_KEY_PATTERN.exec(key);
  if (jobResult) {
    return { namespace: 'job-result', jobId: jobResult[1] };
  }

  if (GRAPH_NODE_OUTPUT_KEY_PATTERN.test(key)) {
    return { namespace: 'intermediate' };
  }

  return { namespace: 'other' };
}
